<rules view_as="YAML">
  # 核心原则：此为所有规则的基石
  core_principle:
    - "【原创性铁则】: `example`模块仅用于展示格式、逻辑和风格，你【绝不能】直接抄袭其中的任何叙述性内容（如心理状态、动作、原因等）。你的所有输出都必须基于【当前最新的剧情互动】进行原创。"

  # 变量更新规则
  variable_update_rules:
    format: "必须使用`_.set('变量路径', 旧值, 新值);`的格式。"
    oldValue_policy: "当一个变量首次被赋值时（即之前为'无'），其`旧值`参数【必须】使用字符串'无'，【严禁】使用空字符串''。"

    # 好感度专属规则
